import { readFile, writeFile } from 'node:fs/promises';

async function bacaPengaturan() {
  try {
    return JSON.parse(await readFile('pengaturan.json', 'utf8'));
  } catch (e) {
    if (e.code === 'ENOENT') return { tema: 'terang' };
    throw e;
  }
}
console.log(await bacaPengaturan());
await writeFile('pengaturan.json', '{"tema":"gelap"}');
console.log(await bacaPengaturan());
try {
  await writeFile('pengaturan.json', '{}', { flag: 'wx' });
} catch (e) {
  console.log(e.code);
}
try {
  await readFile('tidak-ada.txt', 'utf8');
} catch (e) {
  console.log(e.message);
}

