// === a.txt ===
halo
// === main.js ===
import { stat } from 'node:fs/promises';
async function ukuran(nama) {
  try {
    return (await stat(nama)).size;
  } catch (e) {
    if (e.code === 'ENOENT') return -1;
    throw e;
  }
}
console.log(await ukuran('a.txt'), await ukuran('b.txt'));
